import { ReactNode, FC } from 'react';

interface TabItem {
    key: string;
    title: string;
    disabled?: boolean;
    badge?: number | string;
}
interface TabsProps {
    /** 当前激活的 tab (受控) */
    activeKey?: string;
    /** 默认激活的 tab (非受控) */
    defaultActiveKey?: string;
    /** 标签项 */
    items: TabItem[];
    /** 切换回调 */
    onChange?: (key: string | undefined) => void;
    /** 是否可滚动 */
    scrollable?: boolean;
    /** 是否显示指示器 */
    showIndicator?: boolean;
    /** 指示器宽度 (px) */
    indicatorWidth?: number | 'auto';
    /** 自定义类名 */
    className?: string;
    /** 子元素 (TabPanel) */
    children?: ReactNode;
}
interface TabPanelProps {
    /** 对应的 key */
    tabKey: string;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const TabPanel: FC<TabPanelProps>;
type TabsComponent = FC<TabsProps> & {
    Panel: FC<TabPanelProps>;
};
declare const Tabs: TabsComponent;

export { TabPanel, Tabs, Tabs as default };
export type { TabItem, TabPanelProps, TabsProps };
